#!/usr/bin/env python3
# luxarch:fleet-start-gate hook v2 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""After a `/fleet-start` the owner typed with no note, nothing but reading until the owner speaks.

The fleet-start skill ends a no-note start by stating the agent's name, its owner order and its next
step, and waiting for the owner. A sentence in a skill is a request; agents read it and went
straight into issues anyway. This hook makes the wait real:

- UserPromptSubmit: a prompt that is, whole, `/fleet-start` with nothing after it (plain, or as
  Claude Code's `<command-name>` tags with only whitespace and an optional `<command-message>`
  around them) opens the wait for this session, every time the owner types it, after a compact
  too. The owner's next message closes it: a prompt that is, whole, another slash command in
  those tags, or that is not empty and does not open with an envelope tag
  (`<task-notification>`, `<system-reminder>`, any `<tag>`), which Claude Code sends for what the
  owner did not type. A `/fleet-start <note>` never waits, and its note is recorded
  for this session (`fleet-start-after-compact` prints every recorded note back at each
  `/fleet-start` and after each compact). No other prompt is recorded: a tag pasted inside a longer
  prompt is no command. The issue keys in each prompt the owner types are kept for the session
  (`no-new-follow-ups` files an airgapped repo's relayed escalation only under a key the owner
  gave).
- PreToolUse (every tool): while the wait is open, only reading passes, by an allowlist. The tools
  Read, Grep, Glob, Skill, ToolSearch, TaskList, TaskGet and the LuxPM reads
  (`luxpm_list_*`, `luxpm_get_*`, `luxpm_search_*`, `luxpm_find_*`, `luxpm_semantic_search`);
  and a Bash command only when the whole command is one of these shapes, with no `VAR=` prefix and
  none of `; & | < > $ \\` ( ) { } * ? !` or a newline anywhere:
    * `git [-C <checkout>] status|log|diff|show|rev-parse <words>`, `git branch` with only `-a`,
      `-l`, `-v`, `-vv`, `--list`; log, diff and show with no `--output`, `--ext-diff` or `-O` (or
      an abbreviation); `--format=<…>` and `--pretty=<…>` may hold `%` placeholders (`%H`, `%cI`,
      `%s`); `<checkout>` this checkout or the main one;
    * `cat|head|tail|wc|ls|grep <words>`, a word here also holding `'`, `"` or `~`, or a path
      under `$LUXIOS/` (the luxios checkout the iOS texts name);
    * `python3 .claude/hooks/worktree.py list` (`--prune` removes worktrees: after the go-ahead),
      `python3 .claude/hooks/background-shells.py --own`, `command -v <name>`;
    * `docker run --rm -v <checkout>:/repo -w /repo
      [<registry>/luxardolabs/]<luxarch|luxlint|luxaudit>:<version>, `<registry>` one the
      checkout's Makefile or Makefile.local declares (`REGISTRY ?= <host>:<port>`),
      --doc|--docs|--playbook|--changelog|--new-rules <words>`, the shape the docs give, with
      `:ro` on the mount and `--network none` allowed, or with no mount and no `-w` at all (the
      `--changelog --since <v>` form), the options in any order, `<checkout>` the
      checkout the event's `cwd` is in or the main checkout, `<version>` digits and dots, and
      each word a name, a version or `--since` (no other option);
  where a word is `[A-Za-z0-9._/@:=+,-]`. Everything else is denied: edits, writes, questions
  (AskUserQuestion: the three lines end the turn, and the owner answers in their next message),
  subagents, workflows, entering or leaving a worktree (adopting a dead worktree comes after the
  go-ahead), every other MCP tool, LuxPM writes among them, and any other command.

The state lives outside the checkout, in `~/.claude/luxarch-state/<checkout id>/gate/<session>`
(present = waiting), where the shared-machine hook denies every agent write. A session with no
gate file is not waiting. A gate file that cannot be read keeps the session waiting, and the
denial says the state is corrupt; the owner's next message removes it.

An automatic compact types no prompt, so it never opens the wait: the session's go-ahead stands.
"""

from __future__ import annotations

import contextlib
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _ledger import (
    gate_waiting,
    owner_spoke,
    read_event,
    record_note,
    record_owner_keys,
    session_id,
    set_gate,
    start_note,
    state_dir,
    tree_dir,
)

_READ_TOOLS = frozenset(
    {
        "Read",
        "Grep",
        "Glob",
        "Skill",
        "ToolSearch",
        "TaskList",
        "TaskGet",
    }
)
_LUXPM_READ = re.compile(
    r"mcp__luxpm__luxpm_(?:list_\w+|get_\w+|search_\w+|find_\w+|semantic_search)"
)
_META = re.compile(r"[;&|<>$`(){}*?!\\\n\r]")
_W = r"[A-Za-z0-9._/@:=+,-]+"
_GIT_WORD = rf"(?:{_W}|--(?:format|pretty)=[A-Za-z0-9%._:/@,+=-]+)"
_GIT = re.compile(
    rf"git (?P<sub>status|log|diff|show|branch|rev-parse)(?P<rest>(?: {_GIT_WORD})*)"
)
_BRANCH_FLAGS = frozenset({"-a", "-l", "-v", "-vv", "--list"})
# the readers take quoted words and `~` too: none of them has an option that writes
_READERS = re.compile(r"(?:cat|head|tail|wc|ls|grep)(?: [A-Za-z0-9._/@:=+,~'\"-]+)*")
# `list` only: `--prune` removes worktrees, which is a change, after the go-ahead
_WORKTREE = re.compile(r"python3 \.claude/hooks/worktree\.py list")
_GIT_C = re.compile(r"git -C (?P<path>/[A-Za-z0-9._/-]+) (?P<rest>.+)")
# the luxios checkout, as the iOS texts name it: `cat $LUXIOS/VERSION`
# `$LUXIOS`, `$LUXIOS/<path>` or the same in double quotes, as one word
_LUXIOS_WORD = re.compile(r'(?<= )"?\$LUXIOS(?P<rest>/[A-Za-z0-9._/-]*)?"?(?= |$)')
_SHELLS = re.compile(r"python3 \.claude/hooks/background-shells\.py --own")
_COMMAND_V = re.compile(r"command -v [A-Za-z0-9._+-]+")
# the pinned guard image: from the registry this checkout's Makefile or Makefile.local declares
# (the hook ships into public repos, so it names no registry host of its own), or loaded from the
# release tarball on an airgapped machine (`luxarch:X.Y.Z`, the Makefile's REGISTRY empty)
_IMAGE = re.compile(
    r"(?:(?P<registry>[a-z0-9][a-z0-9.-]*(?::[0-9]+)?)/luxardolabs/)?"
    r"(?:luxarch|luxlint|luxaudit):[0-9]+(?:\.[0-9]+)*"
)
# `REGISTRY ?= <host>[:<port>]`, or a guard's own `LUXAUDIT_REGISTRY ?= <host>[:<port>]/luxardolabs`
_REGISTRY_LINE = re.compile(
    r"[ \t]*(?:override[ \t]+)?[A-Z_]*REGISTRY[ \t]*(?:\?|::?)?=[ \t]*"
    r"(?P<host>[a-z0-9][a-z0-9.-]*(?::[0-9]+)?)(?:/luxardolabs)?/?[ \t]*(?:#.*)?"
)
_MAKEFILES = ("Makefile", "Makefile.local")
# a Makefile that is missing, unreadable or not text declares nothing
_UNREADABLE = (OSError, UnicodeDecodeError)
_DOC_FLAGS = frozenset({"--doc", "--docs", "--playbook", "--changelog", "--new-rules"})
# a docs flag's words: names and versions, and `--since` (of `--new-rules`/`--changelog`); never
# another option, since the checkout may be mounted read-write
_DOC_WORD = re.compile(r"[A-Za-z0-9._][A-Za-z0-9._-]*|--since")
_MOUNT = re.compile(r"(?P<path>/[A-Za-z0-9._/-]*):/repo(?::ro)?")
_DOCS_SHAPE = (
    "docker run --rm -v <checkout>:/repo -w /repo "
    "<the Makefile's pinned LUXARCH, LUXLINT or LUXAUDIT image> "
    "--doc <NAME>"
)
_WRITES_OUT = ("--output", "--ext-diff")


def _git_reads(sub: str, words: list[str]) -> bool:
    if sub == "branch":
        return all(w in _BRANCH_FLAGS for w in words)
    if sub in ("log", "diff", "show"):
        for w in words:
            opt = w.split("=", 1)[0]
            if w.startswith("-O") or any(
                opt.startswith(o) or (len(opt) > 3 and o.startswith(opt))
                for o in _WRITES_OUT
            ):
                return False
    return True


def _checkouts() -> set[Path]:
    """The checkout the event's `cwd` is in, and the main checkout."""
    out = {tree_dir()}
    with contextlib.suppress(OSError):
        out.add(state_dir().parent)
    return {p.resolve() for p in out}


def _registries() -> set[str]:
    """The registry hosts the checkouts' Makefile and Makefile.local declare."""
    out: set[str] = set()
    for root in _checkouts():
        for name in _MAKEFILES:
            try:
                text = (root / name).read_text(encoding="utf-8")
            except _UNREADABLE:
                continue
            for line in text.splitlines():
                m = _REGISTRY_LINE.fullmatch(line)
                if m:
                    out.add(m.group("host"))
    return out


def _mounted_checkout(path: str) -> bool:
    if ".." in path.split("/"):
        return False
    return Path(path).resolve() in _checkouts()


def _guard_docs(words: list[str]) -> bool:
    """`docker run --rm` + `-v <checkout>:/repo[:ro]`, `-w /repo` and an optional `--network none`
    (each once, any order) + the fleet registry's guard image + one docs flag and plain words."""
    if words[:3] != ["docker", "run", "--rm"]:
        return False
    rest = words[3:]
    seen: set[str] = set()
    while rest and rest[0] in ("--network", "-v", "-w") and len(rest) >= 2:
        opt, val = rest[0], rest[1]
        if opt in seen:
            return False
        seen.add(opt)
        if opt == "--network" and val != "none":
            return False
        if opt == "-w" and val != "/repo":
            return False
        if opt == "-v":
            m = _MOUNT.fullmatch(val)
            if not m or not _mounted_checkout(m.group("path")):
                return False
        rest = rest[2:]
    # with no mount the image reads nothing of the checkout; a mount comes with `-w /repo`
    if ("-v" in seen) != ("-w" in seen) or len(rest) < 2:
        return False
    image, flag, args = rest[0], rest[1], rest[2:]
    pinned = _IMAGE.fullmatch(image)
    return (
        pinned is not None
        and (
            pinned.group("registry") is None
            or pinned.group("registry") in _registries()
        )
        and flag in _DOC_FLAGS
        and all(_DOC_WORD.fullmatch(a) for a in args)
    )


def read_only(command: str) -> bool:
    """The whole command is one of the reading shapes the wait allows."""
    cmd = command.strip()
    named = _LUXIOS_WORD.sub(lambda m: "LUXIOS" + (m.group("rest") or ""), cmd)
    if named != cmd and _READERS.fullmatch(named) and not _META.search(named):
        return True
    if not cmd or _META.search(cmd):
        return False
    c = _GIT_C.fullmatch(cmd)
    if c:
        if not _mounted_checkout(c.group("path")):
            return False
        cmd = f"git {c.group('rest')}"
    m = _GIT.fullmatch(cmd)
    if m:
        return _git_reads(m.group("sub"), m.group("rest").split())
    if cmd.startswith("docker "):
        return _guard_docs(cmd.split(" "))
    return any(p.fullmatch(cmd) for p in (_READERS, _WORKTREE, _SHELLS, _COMMAND_V))


def _deny(why: str) -> int:
    print(
        "DENIED: you ran `/fleet-start` with no note, so the owner has not said go yet.\n"
        f"{why}\n"
        "End this turn with three lines and wait for the owner's next message:\n"
        "  Agent: your name and role\n"
        "  Owner order: its key and title, or none open\n"
        "  Next step: the one thing you will do first, with its key\n"
        "Reading LuxPM, the repo and the docs stays allowed. Adopting a dead worktree, and every\n"
        "change, comes after the owner's go-ahead.",
        file=sys.stderr,
    )
    return 2


def main() -> int:
    ev = read_event()
    sid = session_id()
    if ev.get("hook_event_name") == "UserPromptSubmit":
        prompt = str(ev.get("prompt") or "")
        note = start_note(prompt)
        if note:
            record_note(note)
        if note is not None or owner_spoke(prompt):
            record_owner_keys(
                prompt
            )  # a relayed escalation's key is one the owner typed
        with contextlib.suppress(OSError, ValueError):
            if note is not None:
                set_gate(
                    sid, note == ""
                )  # a no-note start opens the wait; a note is the go-ahead
            elif owner_spoke(prompt):
                set_gate(sid, False)  # the owner has spoken
        return 0
    waiting, corrupt = gate_waiting(sid)
    if not waiting:
        return 0
    if corrupt:
        return _deny(
            f"The fleet-start state is corrupt ({corrupt}): the session waits until the "
            "owner's next message."
        )
    name = str(ev.get("tool_name") or "")
    if name in _READ_TOOLS or _LUXPM_READ.fullmatch(name):
        return 0
    if name == "Bash":
        ti = ev.get("tool_input")
        command = ti.get("command") if isinstance(ti, dict) else None
        if isinstance(command, str) and read_only(command):
            return 0
        return _deny(
            "This shell command is not one of the reading shapes the wait allows. A guard's docs\n"
            f"read as, written out whole: {_DOCS_SHAPE}\n"
            "(`--doc` or `--docs`, `--playbook`, `--changelog`, `--new-rules`; `<checkout>` the\n"
            "absolute path of this checkout or the main one)."
        )
    return _deny(
        f"`{name or 'this tool'}` is not one of the reading tools the wait allows."
    )


if __name__ == "__main__":
    sys.exit(main())
